import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"إصدار الوثائق وملاحظات الصيانة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0099-文档版本与维护说明.md","filePath":"ar/0099-文档版本与维护说明.md"}'),r={name:"ar/0099-文档版本与维护说明.md"};function o(h,a,d,n,s,u){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="إصدار-الوثائق-وملاحظات-الصيانة" tabindex="-1">إصدار الوثائق وملاحظات الصيانة <a class="header-anchor" href="#إصدار-الوثائق-وملاحظات-الصيانة" aria-label="Permalink to &quot;إصدار الوثائق وملاحظات الصيانة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>99</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>إدارة الإصدارات، ملاحظات الصيانة، معايير الوثائق، سجل التحديثات، صيانة الإعدادات</td></tr></tbody></table><h2 id="أولاً-نظرة-عامة-على-المنظومة-الوثائقية" tabindex="-1">أولاً: نظرة عامة على المنظومة الوثائقية <a class="header-anchor" href="#أولاً-نظرة-عامة-على-المنظومة-الوثائقية" aria-label="Permalink to &quot;أولاً: نظرة عامة على المنظومة الوثائقية&quot;">​</a></h2><p>تتكون منظومة إعدادات حضارة التكافل المرساة من 100 وثيقة Markdown، مرقمة من 00 إلى 99، مقسمة إلى عشر وحدات كبرى، بواقع 10 وثائق في كل وحدة. تتخذ المنظومة الوثائقية SPEC.md (مواصفة توليد الوثائق) قيداً صارماً، وتتخذ «00-هنغ يوانتشو: نظرة عامة على الكون» مخططاً عاماً، وتفصل وثائق كل وحدة من أبعاد مختلفة، وتستخدم في الختام وثائق الملاحق 90-99 للفهرسة والتجميع والتنظيم. تشكل المنظومة الوثائقية كلها قاعدة معرفة إعدادات متكاملة، متسقة منطقياً، واضحة الطبقات، متبادلة الإحالات.</p><p>يتبع تصميم المنظومة الوثائقية ثلاثة مبادئ كبرى: «التنميط، والهيكلة، وقابلية التوسع». التنميط يعني أن كل وثيقة تركز على موضوع محدد وتقوم مقالاً مستقلاً؛ والهيكلة تعني أن جميع الوثائق تتبع مواصفة تنسيق موحدة تسهل القراءة والاسترجاع؛ وقابلية التوسع تعني أن المنظومة الوثائقية تترك مجالاً واسعاً للتوسع، بما يسمح بالتحسين المستمر للإعدادات عبر مراجعة الوثائق القائمة وإضافة محتويات جديدة.</p><h2 id="ثانياً-قواعد-ترقيم-الإصدارات" tabindex="-1">ثانياً: قواعد ترقيم الإصدارات <a class="header-anchor" href="#ثانياً-قواعد-ترقيم-الإصدارات" aria-label="Permalink to &quot;ثانياً: قواعد ترقيم الإصدارات&quot;">​</a></h2><p>تعتمد المنظومة الوثائقية قاعدة ترقيم ثلاثية المستويات «الإصدار الرئيسي.الإصدار الفرعي.رقم المراجعة»:</p><table tabindex="0"><thead><tr><th>مستوى الإصدار</th><th>قاعدة الترقيم</th><th>شرط التفعيل</th><th>مثال</th></tr></thead><tbody><tr><td>الإصدار الرئيسي</td><td>يبدأ من 1 ويزداد</td><td>تعديل معماري جوهري للمنظومة، مثل إعادة تقسيم الوحدات أو تغيير الإعدادات الجوهرية</td><td>v1.0 ← v2.0</td></tr><tr><td>الإصدار الفرعي</td><td>يبدأ من 0 ويزداد</td><td>مراجعة جوهرية لمحتوى وثيقة ما، أو إضافة محتويات إعدادات مهمة</td><td>v1.0 ← v1.1</td></tr><tr><td>رقم المراجعة</td><td>يبدأ من 0 ويزداد</td><td>تعديلات غير جوهرية مثل تصحيحات النصوص وتعديل التنسيق وتوحيد المصطلحات</td><td>v1.0 ← v1.0.1</td></tr></tbody></table><p>الإصدار العام الحالي للمنظومة الوثائقية هو v1.0، أي إصدار النشر الكامل الأول. تسجل كل وثيقة رقم إصدارها الخاص في كتلة معلوماتها الوثائقية، ويُسجل رقم الإصدار العام للمنظومة بصورة موحدة في هذه الوثيقة.</p><h2 id="ثالثاً-استعراض-مواصفات-تنسيق-الوثائق" tabindex="-1">ثالثاً: استعراض مواصفات تنسيق الوثائق <a class="header-anchor" href="#ثالثاً-استعراض-مواصفات-تنسيق-الوثائق" aria-label="Permalink to &quot;ثالثاً: استعراض مواصفات تنسيق الوثائق&quot;">​</a></h2><p>يجب أن تلتزم جميع الوثائق بمواصفات التنسيق الموحدة التالية (التفاصيل في SPEC.md):</p><h3 id="_3-1-تسمية-الملفات" tabindex="-1">3.1 تسمية الملفات <a class="header-anchor" href="#_3-1-تسمية-الملفات" aria-label="Permalink to &quot;3.1 تسمية الملفات&quot;">​</a></h3><p>صيغة اسم الملف هي <code>XX-عنوان الوثيقة.md</code>، حيث XX رقم من خانتين من 00 إلى 99، والعنوان باللغة الصينية دون مسافات.</p><h3 id="_3-2-بنية-الوثيقة" tabindex="-1">3.2 بنية الوثيقة <a class="header-anchor" href="#_3-2-بنية-الوثيقة" aria-label="Permalink to &quot;3.2 بنية الوثيقة&quot;">​</a></h3><p>يجب أن تحتوي كل وثيقة على العناصر البنيوية التالية:</p><ol><li><strong>عنوان المستوى الأول</strong>: عنوان الوثيقة (مطابق لاسم الملف)</li><li><strong>كتلة معلومات الوثيقة</strong>: جدول الرقم والوحدة والكلمات المفتاحية الجوهرية (3-5)</li><li><strong>المتن</strong>: ما لا يقل عن 3 فصول بعناوين المستوى الثاني، باستخدام عناصر بنيوية مثل القوائم والجداول</li><li><strong>الخلاصة</strong>: فقرة تلخيص موجزة</li><li><strong>الوثائق ذات الصلة</strong>: إدراج 2-3 أرقام وأسماء وثائق ذات صلة</li></ol><h3 id="_3-3-اشتراط-الحجم" tabindex="-1">3.3 اشتراط الحجم <a class="header-anchor" href="#_3-3-اشتراط-الحجم" aria-label="Permalink to &quot;3.3 اشتراط الحجم&quot;">​</a></h3><p>يجب ألا يقل متن كل وثيقة عن 800 حرف (دون العناوين والمعلومات الوصفية).</p><h3 id="_3-4-أسلوب-الكتابة" tabindex="-1">3.4 أسلوب الكتابة <a class="header-anchor" href="#_3-4-أسلوب-الكتابة" aria-label="Permalink to &quot;3.4 أسلوب الكتابة&quot;">​</a></h3><ul><li>أسلوب وثائق إعدادات جاد ومنظومي، يشبه الموسوعة/مجموعة الإعدادات</li><li>استخدام مصطلحات موحدة مثل «كون هنغ يوان» و«المرساة» و«التكافل»</li><li>يجب أن تكون الإعدادات الجديدة المضافة متسقة منطقياً مع الإعدادات القائمة، ومطابقة لمبدأ «الواقع أساس، والارتقاء عبر القوانين»</li></ul><h2 id="رابعاً-منظمة-الصيانة-والمسؤوليات" tabindex="-1">رابعاً: منظمة الصيانة والمسؤوليات <a class="header-anchor" href="#رابعاً-منظمة-الصيانة-والمسؤوليات" aria-label="Permalink to &quot;رابعاً: منظمة الصيانة والمسؤوليات&quot;">​</a></h2><h3 id="_4-1-لجنة-صيانة-الإعدادات" tabindex="-1">4.1 لجنة صيانة الإعدادات <a class="header-anchor" href="#_4-1-لجنة-صيانة-الإعدادات" aria-label="Permalink to &quot;4.1 لجنة صيانة الإعدادات&quot;">​</a></h3><p>لجنة صيانة الإعدادات هي أعلى هيئة صيانة للمنظومة الوثائقية، وتتكون من مبدعي إعدادات مخضرمين وخبراء تحقق منطقي وممثلين عن المستخدمين. تشمل مسؤولياتها الجوهرية:</p><ul><li>إقرار البنية العامة للمنظومة الوثائقية وخطط المراجعة الكبرى</li><li>مراجعة التغييرات الجوهرية للإعدادات بما يضمن اتساقها مع الإعدادات الجوهرية</li><li>الفصل في نزاعات الإعدادات وتقديم تفسيرات موثوقة</li><li>تنظيم فحص ذاتي شامل لاتساق الإعدادات دورياً</li><li>إصدار تحديثات الإصدار العام للمنظومة الوثائقية</li></ul><h3 id="_4-2-القائمون-على-صيانة-الوحدات" tabindex="-1">4.2 القائمون على صيانة الوحدات <a class="header-anchor" href="#_4-2-القائمون-على-صيانة-الوحدات" aria-label="Permalink to &quot;4.2 القائمون على صيانة الوحدات&quot;">​</a></h3><p>تعين كل وحدة قائماً واحداً على صيانتها، مسؤولاً عن الصيانة اليومية لوثائق الوحدة العشر. تشمل مسؤولياته:</p><ul><li>تتبع اتساق الإعدادات في وثائق الوحدة</li><li>مراجعة طلبات مراجعة وثائق الوحدة</li><li>تنسيق الإحالات المتبادلة بين وثائق الوحدة</li><li>جمع ملاحظات المستخدمين واقتراحاتهم حول محتوى الوحدة</li><li>رفع تقارير دورية عن حالة صيانة الوحدة إلى لجنة صيانة الإعدادات</li></ul><h3 id="_4-3-مبدعو-الوثائق" tabindex="-1">4.3 مبدعو الوثائق <a class="header-anchor" href="#_4-3-مبدعو-الوثائق" aria-label="Permalink to &quot;4.3 مبدعو الوثائق&quot;">​</a></h3><p>يمكن لأي مبدع مؤهل المشاركة في تأليف ومراجعة الوثائق. تشمل مسؤوليات المبدعين:</p><ul><li>تأليف أو مراجعة الوثائق وفق مواصفات التنسيق</li><li>ضمان اجتياز المحتوى المؤلف لفحص قائمة الفحص الذاتي لتناقضات الإعدادات</li><li>إرفاق وصف تفصيلي للمراجعة عند تقديمها</li><li>التعاون مع أعمال مراجعة القائمين واللجنة</li></ul><h2 id="خامساً-عملية-المراجعة" tabindex="-1">خامساً: عملية المراجعة <a class="header-anchor" href="#خامساً-عملية-المراجعة" aria-label="Permalink to &quot;خامساً: عملية المراجعة&quot;">​</a></h2><h3 id="_5-1-عملية-المراجعة-العادية" tabindex="-1">5.1 عملية المراجعة العادية <a class="header-anchor" href="#_5-1-عملية-المراجعة-العادية" aria-label="Permalink to &quot;5.1 عملية المراجعة العادية&quot;">​</a></h3><ol><li><strong>تقديم طلب</strong>: يقدم المبدع طلب مراجعة إلى القائم على صيانة الوحدة، يتضمن رقم الوثيقة المراد مراجعتها ووصف محتوى المراجعة وأسباب المراجعة.</li><li><strong>مراجعة الوحدة</strong>: يراجع القائم على صيانة الوحدة محتوى المراجعة، مع التركيز على مواصفات التنسيق والاتساق داخل الوحدة. بعد الموافقة يُحال إلى لجنة صيانة الإعدادات.</li><li><strong>إقرار اللجنة</strong>: تجري لجنة صيانة الإعدادات الإقرار النهائي لمحتوى المراجعة، مع التركيز على الاتساق بين الوحدات واتساق الإعدادات الجوهرية.</li><li><strong>تنفيذ المراجعة</strong>: بعد الإقرار، ينفذ القائم على صيانة الوحدة أو المؤلف الأصلي مراجعة الوثيقة.</li><li><strong>تحديث الإصدار</strong>: بعد اكتمال المراجعة، يُحدَّث رقم إصدار الوثيقة ويُسجل في سجل التحديثات لهذه الوثيقة.</li><li><strong>مزامنة الوثائق ذات الصلة</strong>: إذا كان محتوى المراجعة يؤثر في وثائق أخرى، فيجب مراجعة الوثائق ذات الصلة بالتزامن.</li></ol><h3 id="_5-2-عملية-المراجعة-الطارئة" tabindex="-1">5.2 عملية المراجعة الطارئة <a class="header-anchor" href="#_5-2-عملية-المراجعة-الطارئة" aria-label="Permalink to &quot;5.2 عملية المراجعة الطارئة&quot;">​</a></h3><p>بالنسبة للحالات الطارئة التي يُكتشف فيها تناقضات أو أخطاء إعدادات خطيرة، يمكن إطلاق عملية المراجعة الطارئة:</p><ol><li><strong>البلاغ الطارئ</strong>: يبلغ مكتشف المشكلة لجنة صيانة الإعدادات فوراً.</li><li><strong>الإقرار السريع</strong>: تكمل اللجنة الإقرار الطارئ خلال 24 ساعة وتقدم خطة المراجعة.</li><li><strong>تنفيذ المراجعة</strong>: تعيين شخص مخصص للتنفيذ الفوري.</li><li><strong>التسجيل اللاحق</strong>: بعد اكتمال المراجعة، يُسجل طلب المراجعة وسجلات الإقرار بأثر رجعي.</li></ol><h3 id="_5-3-المراجعة-الشاملة-الدورية" tabindex="-1">5.3 المراجعة الشاملة الدورية <a class="header-anchor" href="#_5-3-المراجعة-الشاملة-الدورية" aria-label="Permalink to &quot;5.3 المراجعة الشاملة الدورية&quot;">​</a></h3><p>تنظم لجنة صيانة الإعدادات مراجعة شاملة للمنظومة الوثائقية مرة كل عام، تشمل:</p><ul><li>فحصاً ذاتياً شاملاً لاتساق الإعدادات</li><li>معالجة مركزية لملاحظات المستخدمين</li><li>توحيد وتحديث المنظومة المصطلحية</li><li>تحديثاً متزامناً لوثائق الفهارس</li><li>فحصاً وتصحيحاً موحدين لتنسيقات الوثائق</li></ul><h2 id="سادساً-سجل-التحديثات" tabindex="-1">سادساً: سجل التحديثات <a class="header-anchor" href="#سادساً-سجل-التحديثات" aria-label="Permalink to &quot;سادساً: سجل التحديثات&quot;">​</a></h2><h3 id="v1-0-النشر-الكامل-الأول" tabindex="-1">v1.0 (النشر الكامل الأول) <a class="header-anchor" href="#v1-0-النشر-الكامل-الأول" aria-label="Permalink to &quot;v1.0 (النشر الكامل الأول)&quot;">​</a></h3><ul><li>إتمام تأليف ونشر الوثائق المئة كلها</li><li>وضع البنية الكاملة للمنظومة الوثائقية ومواصفات التنسيق</li><li>إتمام تغطية محتويات الوحدات العشر الكبرى</li><li>إقامة منظومة فهارس الملاحق (معجم المصطلحات، وفهرس الأنظمة، والفهرس القانوني، والسجل التاريخي، وسجل عشرة آلاف عرق، والشخصيات والمنظمات، والأسئلة الشائعة، وقائمة الفحص الذاتي، واقتراحات التوسع، وملاحظات الإصدار)</li></ul><h3 id="منطقة-تسجيل-تحديثات-الإصدارات-اللاحقة" tabindex="-1">منطقة تسجيل تحديثات الإصدارات اللاحقة <a class="header-anchor" href="#منطقة-تسجيل-تحديثات-الإصدارات-اللاحقة" aria-label="Permalink to &quot;منطقة تسجيل تحديثات الإصدارات اللاحقة&quot;">​</a></h3><p>(ستُضاف هنا محتويات تحديثات الإصدارات اللاحقة، بما فيها رقم الإصدار وتاريخ النشر وملخص المحتويات الرئيسية للتحديث)</p><h2 id="سابعاً-مواصفات-الاستشهاد-والإحالات-المتبادلة-للوثائق" tabindex="-1">سابعاً: مواصفات الاستشهاد والإحالات المتبادلة للوثائق <a class="header-anchor" href="#سابعاً-مواصفات-الاستشهاد-والإحالات-المتبادلة-للوثائق" aria-label="Permalink to &quot;سابعاً: مواصفات الاستشهاد والإحالات المتبادلة للوثائق&quot;">​</a></h2><h3 id="_7-1-الاستشهادات-الداخلية" tabindex="-1">7.1 الاستشهادات الداخلية <a class="header-anchor" href="#_7-1-الاستشهادات-الداخلية" aria-label="Permalink to &quot;7.1 الاستشهادات الداخلية&quot;">​</a></h3><p>تستخدم الإحالات المتبادلة بين الوثائق صيغة «رقم الوثيقة-عنوان الوثيقة»، مثل «انظر الوثيقة 84 «الإطار العام للبروتوكولات الأثرية»». ويجب عند الاستشهاد التأكد من أن الوثيقة المستشهد بها موجودة فعلاً وأن الرقم والعنوان صحيحان.</p><h3 id="_7-2-الاستشهادات-المصطلحية" tabindex="-1">7.2 الاستشهادات المصطلحية <a class="header-anchor" href="#_7-2-الاستشهادات-المصطلحية" aria-label="Permalink to &quot;7.2 الاستشهادات المصطلحية&quot;">​</a></h3><p>عند أول استخدام لمصطلح جوهري، يمكن الإشارة إلى القيد المقابل في الوثيقة 90 «معجم المصطلحات». ولا حاجة لإعادة الإشارة عند الاستخدامات اللاحقة لنفس المصطلح.</p><h3 id="_7-3-الاستشهادات-الخارجية" tabindex="-1">7.3 الاستشهادات الخارجية <a class="header-anchor" href="#_7-3-الاستشهادات-الخارجية" aria-label="Permalink to &quot;7.3 الاستشهادات الخارجية&quot;">​</a></h3><p>إذا لزم الاستشهاد بمواد واقعية أو أعمال خيالية خارج منظومة الإعدادات، يجب ذكر المصدر، وتوضيح أن هذا الاستشهاد مادة مرجعية في إطار مبدأ «الواقع أساس»، ولا يمثل اعتماد المنظومة الكامل لمحتواه.</p><h2 id="ثامناً-آليات-ضمان-الجودة" tabindex="-1">ثامناً: آليات ضمان الجودة <a class="header-anchor" href="#ثامناً-آليات-ضمان-الجودة" aria-label="Permalink to &quot;ثامناً: آليات ضمان الجودة&quot;">​</a></h2><h3 id="_8-1-الفحص-الذاتي-لتناقضات-الإعدادات" tabindex="-1">8.1 الفحص الذاتي لتناقضات الإعدادات <a class="header-anchor" href="#_8-1-الفحص-الذاتي-لتناقضات-الإعدادات" aria-label="Permalink to &quot;8.1 الفحص الذاتي لتناقضات الإعدادات&quot;">​</a></h3><p>يجب أن تجتاز جميع الوثائق المؤلفة حديثاً والمراجَعة جميع بنود فحص قائمة الفحص الذاتي لتناقضات الإعدادات (الوثيقة 97)، التي تضم أكثر من 40 بنداً في ثلاث فئات كبرى: اتساق الإعدادات الجوهرية، والاتساق المنطقي بين الوحدات، ومواصفات تنسيق الوثائق.</p><h3 id="_8-2-المراجعة-المتبادلة" tabindex="-1">8.2 المراجعة المتبادلة <a class="header-anchor" href="#_8-2-المراجعة-المتبادلة" aria-label="Permalink to &quot;8.2 المراجعة المتبادلة&quot;">​</a></h3><p>يجب أن تخضع كل وثيقة قبل نشرها الرسمي لمراجعة متبادلة من مبدع آخر واحد على الأقل، مع التركيز على الاتساق المنطقي بين الوحدات وتوحيد المصطلحات.</p><h3 id="_8-3-آلية-ملاحظات-المستخدمين" tabindex="-1">8.3 آلية ملاحظات المستخدمين <a class="header-anchor" href="#_8-3-آلية-ملاحظات-المستخدمين" aria-label="Permalink to &quot;8.3 آلية ملاحظات المستخدمين&quot;">​</a></h3><p>تنشئ المنظومة الوثائقية قنوات لملاحظات المستخدمين؛ يمكن للمستخدمين تقديم الملاحظات عبر الوسائل التالية:</p><ul><li>الإبلاغ عن تناقضات الإعدادات والأخطاء المنطقية</li><li>إثارة مشكلات عدم توحيد المصطلحات</li><li>اقتراح استكمال أو مراجعة محتويات محددة</li><li>الإشارة إلى أخطاء التنسيق والنصوص</li></ul><p>تتولى القائمون على صيانة الوحدات معالجة جميع الملاحظات مصنفة، وتُحال الملاحظات المهمة إلى لجنة صيانة الإعدادات للمداولة.</p><h3 id="_8-4-التقرير-الفصلي-للاتساق" tabindex="-1">8.4 التقرير الفصلي للاتساق <a class="header-anchor" href="#_8-4-التقرير-الفصلي-للاتساق" aria-label="Permalink to &quot;8.4 التقرير الفصلي للاتساق&quot;">​</a></h3><p>تصدر لجنة صيانة الإعدادات كل فصل «تقرير اتساق الإعدادات»، يتضمن:</p><ul><li>تناقضات الإعدادات المكتشفة في الفصل ومعالجتها</li><li>إحصاءات مراجعات الوثائق في الفصل</li><li>تقدم توحيد المصطلحات</li><li>معالجة ملاحظات المستخدمين</li><li>خطة الصيانة للفصل التالي</li></ul><h2 id="تاسعاً-تخزين-الوثائق-وتوزيعها" tabindex="-1">تاسعاً: تخزين الوثائق وتوزيعها <a class="header-anchor" href="#تاسعاً-تخزين-الوثائق-وتوزيعها" aria-label="Permalink to &quot;تاسعاً: تخزين الوثائق وتوزيعها&quot;">​</a></h2><h3 id="_9-1-صيغة-التخزين" tabindex="-1">9.1 صيغة التخزين <a class="header-anchor" href="#_9-1-صيغة-التخزين" aria-label="Permalink to &quot;9.1 صيغة التخزين&quot;">​</a></h3><p>تُخزن جميع الوثائق بصيغة Markdown (.md)، بما يضمن قابلية القراءة عبر المنصات وسهولة إدارة الإصدارات. تستخدم الوثائق ترميز UTF-8، الداعم للصينية والأحرف الخاصة.</p><h3 id="_9-2-بنية-الدليل" tabindex="-1">9.2 بنية الدليل <a class="header-anchor" href="#_9-2-بنية-الدليل" aria-label="Permalink to &quot;9.2 بنية الدليل&quot;">​</a></h3><p>تُخزن الوثائق بصورة موحدة في دليل <code>anchor-docs/</code>، بأسماء ملفات بصيغة <code>XX-عنوان الوثيقة.md</code>. وتُخزن SPEC.md، بوصفها ملف المواصفات، في الدليل نفسه.</p><h3 id="_9-3-إدارة-الإصدارات" tabindex="-1">9.3 إدارة الإصدارات <a class="header-anchor" href="#_9-3-إدارة-الإصدارات" aria-label="Permalink to &quot;9.3 إدارة الإصدارات&quot;">​</a></h3><p>يُوصى باستخدام أنظمة التحكم بالإصدارات مثل Git لإدارة إصدارات الوثائق، مع إرفاق رسالة commit مفصلة تسجل محتوى وأسباب كل مراجعة مقدمة.</p><h3 id="_9-4-وسائل-التوزيع" tabindex="-1">9.4 وسائل التوزيع <a class="header-anchor" href="#_9-4-وسائل-التوزيع" aria-label="Permalink to &quot;9.4 وسائل التوزيع&quot;">​</a></h3><p>يمكن توزيع المنظومة الوثائقية بالوسائل التالية:</p><ul><li>تعبئتها في أرشيف ZIP للتحميل</li><li>نشرها كموقع ويب ثابت للتصفح عبر الإنترنت</li><li>تحويلها إلى صيغة PDF أو EPUB للقراءة</li><li>استيرادها إلى أنظمة قواعد المعرفة للإدارة المنظمة</li></ul><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>إصدار الوثائق وملاحظات الصيانة هي «الدستور الإداري» لمنظومة إعدادات حضارة التكافل المرساة. فهي ترسي قواعد الإصدار ومنظمة الصيانة وعملية المراجعة وآليات ضمان الجودة ووسائل التخزين والتوزيع للمنظومة الوثائقية، بما يضمن أن تظل هذه المنظومة الواسعة المكونة من 100 وثيقة محافظة على النظام والاتساق دائماً في مسار نموها المستمر. المنظومة الجيدة لا تحتاج إلى محتوى رائع فحسب، بل إلى آلية صيانة كاملة تضمن تطورها الصحي طويل الأمد. وهذه الوثيقة هي الحامل الجوهري لتلك الآلية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (قائمة الفحص الذاتي لتناقضات الإعدادات)</li><li>90-术语词典 (معجم المصطلحات)</li><li>00-衡元宙宇宙总览 (هنغ يوانتشو: نظرة عامة على الكون)</li></ul>',77)])])}const _=l(r,[["render",o]]);export{b as __pageData,_ as default};
